// ===== Modèles d'événement : un même moteur, des modules activés selon le type de lieu =====
const TEMPLATES = [
  { id: 'club', n: 'Boîte de nuit', ex: 'Bisous Bisous, Selva', venue: 'bisous', minAge: 18, sos: ['112', '114'], flags: ['wallet'], tech: 'Balises seules (intérieur, plusieurs niveaux), aucun GPS', kpi: ['Jauge réglementaire en direct', 'Entrées / sorties par quart d’heure', 'Comparaison semaine N-1', 'Tables réservées occupées'], risks: ['Saturation de la piste', 'Escaliers et sorties de secours', 'Consommation d’alcool (alertes médicales)'], visitor: ['Amis sur 2 niveaux (étiquette « autre niveau »)', 'Carte des boissons et prix', 'Vestiaire et file d’attente'] },
  { id: 'festival', n: 'Festival une nuit', ex: 'Le Bal des Fous', venue: 'bdf', minAge: 18, sos: ['112', '114'], flags: ['wallet'], tech: 'GPS en extérieur + balises aux points clés', kpi: ['Heatmap et flux', 'Effet de la programmation', 'Attente aux bars', 'Partenaires : passages et offres'], risks: ['Mouvements de foule devant la scène', 'Réseau mobile saturé'], visitor: ['Retrouver ses amis', 'Bar le moins chargé', 'Point de rendez-vous', 'SOS géolocalisé'] },
  { id: 'multiday', n: 'Festival plusieurs jours + camping', ex: 'type Tomorrowland', venue: 'bdf', ev: 'Festival Horizon (démo)', minAge: 16, sos: ['112'], flags: ['wallet', 'multiday', 'camping', 'family'], tech: 'GPS + balises, carte téléchargée hors ligne', kpi: ['Fréquentation par jour', 'Flux camping ↔ scènes', 'Rotation des visiteurs uniques'], risks: ['Personnes perdues la nuit', 'Batterie des téléphones sur 3 jours'], visitor: ['Programme par jour', '« Ma tente » épinglée sur la carte', 'Mode famille', 'Économie de batterie'] },
  { id: 'concert', n: 'Salle de concert / Zénith', ex: 'salle 6 000 places', venue: 'bdf', ev: 'Zénith · Nuit électro (démo)', minAge: 0, sos: ['112', '114'], flags: ['wallet', 'seats'], tech: 'Balises (intérieur), précision au bloc', kpi: ['Remplissage par bloc et par porte', 'Ouverture des portes → remplissage', 'Sortie échelonnée'], risks: ['Goulots aux portes', 'Sortie simultanée en fin de concert'], visitor: ['Trouver ma place (bloc, rang, siège)', 'Toilettes et bars les plus proches de ma place', 'Sortie conseillée'] },
  { id: 'stadium', n: 'Stade / Grand Prix', ex: 'type Grand Prix de Monaco', venue: 'bdf', ev: 'Grand Prix Village (démo)', minAge: 0, sos: ['112'], flags: ['wallet', 'seats', 'multiday'], tech: 'GPS (grand site extérieur), balises dans les tribunes couvertes', kpi: ['Remplissage des tribunes', 'Flux entre zones payantes', 'Temps d’accès aux tribunes'], risks: ['Accès sécurisés par zone de billet', 'Chaleur et hydratation'], visitor: ['Ma tribune et ma place', 'Zones accessibles selon mon billet', 'Programme des sessions par jour'] },
  { id: 'desert', n: 'Événement sans réseau', ex: 'type Burning Man', venue: 'bdf', ev: 'Black Rock (démo, USA)', minAge: 18, sos: ['911'], flags: ['wallet', 'mesh', 'camping', 'multiday'], tech: 'GPS + relais Bluetooth entre téléphones, carte 100 % hors ligne', kpi: ['Données synchronisées au retour du réseau', 'Densité par secteur', 'Points d’assistance utilisés'], risks: ['Aucun réseau mobile', 'Distances très longues', 'Nuit et tempêtes'], visitor: ['Relais entre téléphones ONEERA (~30 m)', 'Dernière position connue datée', '« Ma tente » et boussole'] },
  { id: 'park', n: 'Parc d’attractions', ex: 'type Disneyland', venue: 'bdf', ev: 'Parc (démo)', minAge: 0, sos: ['112'], flags: ['wallet', 'family', 'queues'], tech: 'GPS + balises dans les files d’attente', kpi: ['Temps d’attente par attraction', 'Répartition de la foule', 'Enfants retrouvés et délai'], risks: ['Enfants perdus', 'Files trop longues'], visitor: ['Mode famille : suivre ses enfants (bracelet)', 'Attente en direct', 'Itinéraire vers l’attraction la moins chargée'] }
];
ST.flags = ST.flags || ['wallet']; ST.template = ST.template || 'festival';
const hasFlag = f => (ST.flags || []).includes(f);
function applyTemplate(id) { const t = TEMPLATES.find(x => x.id === id); if (!t) return; ST.template = id; ST.flags = [...t.flags]; setVenue(t.venue); if (t.ev) EVENT.name = t.ev; logEv('Modèle : ' + t.n); emit(); }
const tpl = () => TEMPLATES.find(t => t.id === ST.template) || TEMPLATES[1];
const demoPlan = () => !!tpl().ev;

// --- billet, bracelet et cashless (toujours disponible)
V.wallet = () => {
  const sb = openSheet(`<h2 class="h2">Billet et cashless</h2>
    <div class="card" style="background:linear-gradient(135deg,#2A1B4A,#7C5BD6);color:#fff;gap:10px"><div style="display:flex;justify-content:space-between"><b>${EVENT.name}</b><span class="pill" style="background:rgba(255,255,255,.2);color:#fff">${hasFlag('multiday') ? 'Pass 3 jours' : 'Entrée soirée'}</span></div>
      <div style="display:flex;gap:12px;align-items:center"><div class="qr" style="width:120px;height:120px;padding:8px;flex-shrink:0"><canvas id="tq"></canvas></div><div style="font-size:13px">${hasFlag('seats') ? '<b>Bloc B · Rang 12 · Siège 8</b><br>' : ''}Billet n° ${VENUE.id.toUpperCase()}-48213<br>Titulaire : ${esc(ST.me.first)}<br><span style="opacity:.8">Scanné à ${fmtClock(clockMin(VENUE.hours.slice(0, 5)) + 41)} · ${POIS.find(o => o.id === 'entree') ? POIS.find(o => o.id === 'entree').n : 'entrée'}</span>${hasFlag('seats') && ST.template === 'stadium' ? '<br><b>Zones d’accès : Tribune K, village, paddock club ✗</b>' : ''}</div></div></div>
    <div class="card" style="flex-direction:row;align-items:center;gap:12px"><img src="${IC('cashless')}" alt="" style="width:46px"><div style="flex:1"><b>Bracelet cashless lié</b><div class="small">Solde : <b id="bal">${(ST.balance ?? 34.5).toFixed(2).replace('.', ',')} €</b> · 4 achats ce soir</div></div><button class="btn sm" id="top">Recharger</button></div>
    <div class="list">${POIS.filter(o => o.bar).slice(0, 2).map((o, i) => { const it = MENU[o.id] ? MENU[o.id][0][1][i] || MENU[o.id][0][1][0] : ['Boisson', 8]; return `<div class="row"><div class="grow"><div class="t">${it[0]} · ${o.n}</div><div class="s">${fmtClock(ST.clock - 24 - i * 21)}</div></div><b>−${it[1].toFixed(2).replace('.', ',')} €</b></div>`; }).join('')}</div>
    <div class="tiny">Le bracelet sert aussi à ajouter un ami : approchez vos deux bracelets d’un téléphone (NFC). Prototype : aucun paiement réel.</div>`);
  drawQR($('#tq', sb), 'ticket-48213');
  $('#top', sb).onclick = () => { const s2 = openSheet(`<h2 class="h2">Recharger le bracelet</h2><div class="grid3">${[10, 20, 50].map(v => `<button class="card" data-v="${v}" style="align-items:center"><b style="font-size:22px">${v} €</b></button>`).join('')}</div><div class="tiny">Apple Pay / Google Pay. Prototype : aucun paiement n’est effectué.</div>`); s2.onclick = e => { const b = e.target.closest('[data-v]'); if (!b) return; ST.balance = (ST.balance ?? 34.5) + +b.dataset.v; closeSheet(); toast(`Bracelet rechargé : +${b.dataset.v} € (simulation)`); }; };
};
// --- trouver sa place (salle, stade)
V.mySeat = () => { const seatAt = VENUE.id === 'bdf' ? [55, 41] : POIS[0].at; V.goTo(seatAt, 'Ta place · Bloc B, rang 12, siège 8', nearestNode(seatAt)); toast('Itinéraire vers ta place · entrée conseillée : porte B (moins chargée)'); };
// --- mode famille : enfant suivi par son bracelet
const CHILD = { n: 'Lina (8 ans)', at: [44, 56], av: { ...AV_DEFAULT, ...AV_PRESETS[5], hair: 'buns', top: 'tee', topC: 4, bottom: 'shorts', bottomC: 7 } };
V.family = () => {
  const on = hasFlag('familyOn');
  const sb = openSheet(`<h2 class="h2">Mode famille</h2><div class="card" style="flex-direction:row;gap:12px;align-items:center"><img src="${avURI(CHILD.av)}" alt="" style="width:56px;height:56px;border-radius:28px;background:#EEF2FF"><div style="flex:1"><b>${CHILD.n}</b><div class="small">Bracelet enfant n° 7731 · lié à ton compte</div></div><span class="tog ${on ? 'on' : ''}" id="ft" role="switch" aria-checked="${on}"></span></div><div class="pill ${on ? 'ok' : 'gray'}" style="align-self:flex-start">${on ? 'Lina suivie · bracelet détecté il y a 20 s' : 'Suivi désactivé : touche l’interrupteur pour suivre Lina'}</div>
    <button class="card" id="photo" style="flex-direction:row;gap:10px;align-items:center;text-align:left;background:#F3F5FB"><div class="ico" style="background:#fff">${I.camera}</div><div style="flex:1"><b>${ST.childPhoto ? 'Photo du jour enregistrée ✓' : 'Prendre une photo de Lina aujourd’hui'}</b><div class="small">Tenue du jour : envoyée à la sécurité seulement si tu la déclares perdue</div></div></button>
    <div class="list" style="${on ? '' : 'opacity:.45;pointer-events:none'}">${[['Alerte si Lina s’éloigne de plus de 50 m', true], ['Alerte si Lina sort de la zone famille', true], ['Partager avec un autre parent', false]].map(r => `<button class="row"><div class="grow"><div class="t">${r[0]}</div></div><span class="tog ${r[1] ? 'on' : ''}"></span></button>`).join('')}</div><button class="link" id="addc" style="justify-content:flex-start">+ Ajouter un autre enfant</button>
    <button class="btn red" id="lost">Je ne trouve plus ${CHILD.n.split(' ')[0]}</button><div class="tiny">Le bracelet enfant n’a pas de téléphone : il est repéré par les balises et les téléphones du staff à proximité. Sa position n’est visible que par ses parents et la sécurité.</div>`);
  sb.onclick = e => { const r = e.target.closest('.row'); if (r) r.querySelector('.tog').classList.toggle('on'); };
  $('#ft', sb).onclick = e => { e.stopPropagation(); if (hasFlag('familyOn')) ST.flags = ST.flags.filter(x => x !== 'familyOn'); else ST.flags.push('familyOn'); emit(); V.family(); };
  $('#photo', sb).onclick = async () => { const v = await sysAlert({ title: 'Appareil photo', text: 'Prototype : la photo reste sur ton téléphone et n’est envoyée à la sécurité que si tu déclares Lina perdue.', buttons: [{ t: 'Prendre la photo', v: 1, b: 1 }, { t: 'Annuler', v: 0 }] }); if (v) { ST.childPhoto = true; V.family(); } };
  $('#addc', sb).onclick = () => toast('Prototype : lier un autre bracelet enfant (scan NFC)');
  $('#lost', sb).onclick = () => { closeSheet(true); ST.reports.unshift({ id: Date.now() % 100000, cat: 'child', label: 'Enfant perdu : ' + CHILD.n, note: 'Bracelet 7731 · dernière détection il y a 1 min', at: [...CHILD.at], zone: zoneOf(CHILD.at), time: fmtClock(ST.clock), status: 'Reçue', by: '@' + ST.me.pseudo, mine: true, prio: 'Critique', hist: [[fmtClock(ST.clock), 'Alerte enfant perdu : toute la sécurité est prévenue', 'Reçue']] }); emit(); if (!hasFlag('familyOn')) ST.flags.push('familyOn'); V.map({ at: CHILD.at, zoom: .6 }); toast(ST.childPhoto ? 'La sécurité a reçu sa photo du jour et sa dernière position' : 'La sécurité a reçu sa description (avatar) et sa dernière position'); };
};
// --- ma tente (camping)
V.tent = (at) => { ST.tents = ST.tents || {}; ST.tents[VENUE.id] = at || [...ST.me.pos]; emit(); toast('Ta tente est épinglée : itinéraire possible même hors réseau'); };
